  total: string;
  payments: InvoicePaymentView[];
  paid: string;
  amountDue: string;
  writtenOff: string;
  // The date (yyyy-mm-dd) of the payment that cleared it, payments in date order; null while not fully paid.
  paidDate: string | null;
